class Base {
    long data; // Object size impacted by vptr
public:
    virtual void dyn_dispatch() const {} // VTable entry generated
    void static_dispatch() const {}      // No VTable entry
};

class Derived : public Base {
public:
    void dyn_dispatch() const override {} // Overrides vtable entry
};

// Memory: sizeof(Base) includes 'data' + compiler vptr

// STATIC DISPATCH (Compile time resolve)
Base b;
b.static_dispatch();

// DYNAMIC DISPATCH (Runtime resolve via vtable)
Base* p = new Derived();
p->dyn_dispatch(); // Follows vptr -> VTable[index]

// Note: `final` class/methods enable devirtualization
// (Optimizing dynamic calls to static ones)
